    value.ir_type == "String"
    regex.match(".*\\*.*", value.value)
} else {
    value.ir_type == "Array"
    some elem in value.value
    elem.ir_type == "String"
    regex.match(".*\\*.*", elem.value)
}

check_runtime_privilege(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "Integer"
    value.value == 0
}

