import data.glitch_lib

# Helper function to check if a string contains SSH and root patterns
check_unnecessary_privileges(str_value) {
    regex.match(".*ssh.*", str_value)
    regex.match(".*root@.*", str_value)
}

# Helper function to get string representation from various node types
get_string_representation(node) = str {
    node.ir_type == "String"
    str := node.value
} else {
    node.ir_type == "VariableReference"
    str := node.value
} else {
    # For complex expressions, try to extract from code field
    node.code != ""
    str := node.code
} else {
    # Fallback to empty string
    str := ""
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for command execution resources in different IaC technologies
    node.type in {"exec", "shell", "command", "script", "execute", "remote_exec"}

    # Get all attributes of the atomic unit
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Focus on command-related attributes
    attr.name in {"command", "cmd", "script", "action", "shell", "execute"}

    # Get string representation of the attribute value
    str_value := get_string_representation(attr.value)

    # Check for SSH and root patterns in the command
    check_unnecessary_privileges(str_value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Command uses SSH to run as root, which may be unnecessary. (CWE-250)"
    }
}

